import{_ as o,o as t,c as n,a as r}from"./app.Dzj71sBz.js";const g=JSON.parse('{"title":"Two-Surface Architecture Proposal","description":"","frontmatter":{"title":"Two-Surface Architecture Proposal","date":"2026-02-21T00:00:00.000Z","status":"accepted","owner":"B90-W3-agent-a","tags":["wl-136","architecture","cli","decomposition"]},"headers":[],"relativePath":"changes/two-surface-architecture/proposal.md","filePath":"changes/two-surface-architecture/proposal.md","lastUpdated":1771678191000}'),i={name:"changes/two-surface-architecture/proposal.md"};function a(s,e,c,d,l,u){return t(),n("div",null,[...e[0]||(e[0]=[r('<h1 id="two-surface-architecture-proposal" tabindex="-1">Two-Surface Architecture Proposal <a class="header-anchor" href="#two-surface-architecture-proposal" aria-label="Permalink to &quot;Two-Surface Architecture Proposal&quot;">​</a></h1><h2 id="summary" tabindex="-1">Summary <a class="header-anchor" href="#summary" aria-label="Permalink to &quot;Summary&quot;">​</a></h2><p>thegent&#39;s Python codebase is split into two distinct surfaces: <strong>core</strong> and <strong>tooling</strong>. This separation was initiated in Wave-1 (WL-120) and formalized in Wave-2 (WL-136, B90-W2-D2). The two-surface split enforces a strict import boundary and allows the tooling surface to be omitted from production deployments.</p><h2 id="the-core-surface" tabindex="-1">The Core Surface <a class="header-anchor" href="#the-core-surface" aria-label="Permalink to &quot;The Core Surface&quot;">​</a></h2><p>The <strong>core</strong> surface contains the production runtime path of thegent:</p><ul><li>undefined<strong>Orchestration</strong>: <code>src/thegent/agents/</code>, <code>src/thegent/orchestration/</code></li><li>undefined<strong>MCP server</strong>: <code>src/thegent/mcp/</code></li><li>undefined<strong>Routing</strong>: <code>src/thegent/routing/</code></li><li>undefined<strong>Governance runtime</strong>: <code>src/thegent/governance/</code> (SLO emitters, policy engine)</li><li>undefined<strong>Infrastructure</strong>: <code>src/thegent/infra/</code></li><li>undefined<strong>Configuration</strong>: <code>src/thegent/config.py</code>, <code>src/thegent/config/</code></li><li>undefined<strong>Session management</strong>: <code>src/thegent/session/</code></li><li>undefined<strong>Core CLI dispatch</strong>: <code>src/thegent/cli/commands/impl.py</code>, <code>src/thegent/cli/commands/run_cmds.py</code></li></ul><p>Core modules are performance-critical and must start quickly. They must not import tooling modules. Core is the surface deployed to production and embedded in agent runtimes.</p><h2 id="the-tooling-surface" tabindex="-1">The Tooling Surface <a class="header-anchor" href="#the-tooling-surface" aria-label="Permalink to &quot;The Tooling Surface&quot;">​</a></h2><p>The <strong>tooling</strong> surface contains development utilities, research helpers, benchmarks, audit commands, and QA workflows:</p><ul><li>undefined<strong>DAG CLI commands</strong>: <code>src/thegent/cli/commands/cli_dag.py</code> — dag_* orchestration commands for managing DAG sessions. These are developer and orchestration tooling.</li><li>undefined<strong>Tooling CLI commands</strong>: <code>src/thegent/cli/commands/cli_tooling.py</code> — audit_verify, benchmark, deep_research, drift_monitor, roadmap commands.</li><li>undefined<strong>Execution boundary shim</strong>: <code>src/thegent/cli/commands/impl_execution.py</code> — thin shim re-exporting core execution functions; lives in the CLI surface.</li><li>undefined<strong>Benchmarking</strong>: <code>benchmarks/</code></li><li>undefined<strong>Scripts</strong>: <code>scripts/</code> — collection, analysis, rendering</li></ul><p>Tooling modules may import core modules. Core modules MUST NOT import tooling modules.</p><h2 id="motivation" tabindex="-1">Motivation <a class="header-anchor" href="#motivation" aria-label="Permalink to &quot;Motivation&quot;">​</a></h2><ol><li>undefined<strong>Startup performance</strong>: Core CLI (<code>thegent run</code>, <code>thegent bg</code>) must start in under 250ms. Importing heavy tooling at startup violates the CLI SLO.</li><li>undefined<strong>Deployment footprint</strong>: Production containers do not need research/benchmarking code; the two-surface split enables slimmer images.</li><li>undefined<strong>Separation of responsibilities</strong>: Tooling evolves at a different cadence than core. Decoupling prevents tooling churn from breaking core contracts.</li><li>undefined<strong>Test isolation</strong>: Core unit tests run without tooling deps; tooling tests may require heavier fixtures.</li></ol><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><p>Split all CLI commands into core (production path) and tooling (developer/QA path), with a machine-enforced import boundary. Violations are detected by <code>scripts/check_thegent_core_boundary.py</code> and blocked in CI.</p><h2 id="alternatives-considered" tabindex="-1">Alternatives Considered <a class="header-anchor" href="#alternatives-considered" aria-label="Permalink to &quot;Alternatives Considered&quot;">​</a></h2><ul><li>undefined<strong>Single surface</strong>: Rejected. Monolithic CLI.py (6,994 LOC) is unmaintainable and violates startup SLOs.</li><li>undefined<strong>Plugin architecture</strong>: Considered for Wave-5+. The current split is a prerequisite.</li><li>undefined<strong>Separate packages</strong>: Deferred. Two-surface within the same package is sufficient for now and avoids packaging complexity.</li></ul>',17)])])}const m=o(i,[["render",a]]);export{g as __pageData,m as default};
